gsap.registerPlugin(ScrollTrigger, CustomEase);

let lenis;
let staggerDefault = 0.07;
let durationDefault = 1.47;
let transitionOffset = 200; /* ms */

CustomEase.create("cubic-default", "0.625, 0.05, 0, 1");
gsap.defaults({ease: "cubic-default", duration: durationDefault});

initPageTransitions();

// Animation - Page Loader
function initLoader() {

  var tl = gsap.timeline();

  tl.call(function () {
    lenis.stop();
  }, null, 0);

  tl.call(function () {
    pageTransitionOut();
  }, null, 0.105);
  
  tl.to('.loading-screen', {
    opacity: 0,
    duration: 0.2,
    ease: "none",
  }, 0.105);

}

// Animation - Page Leave
function pageTransitionIn() {
  var tl = gsap.timeline();

  if (document.querySelector('.lorem-ipsum')) {}

  tl.call(function () {
    lenis.stop();
  });
  
  tl.fromTo('.loading-screen', {
    opacity: 0,
  },{
    opacity: 1,
    duration: 0.2,
    ease: "none",
  }, 0);
  
  tl.to('.loading-screen', {
    opacity: 0,
    duration: 0.2,
    ease: "none",
    delay: 0.05
  });
}

// Animation - Page Enter
function pageTransitionOut() {
  var tl = gsap.timeline();

  tl.call(function () {
    lenis.stop();
    lenis.scrollTo(0, { immediate: true, force: true, lock: true, duration: 0.0166 });
    lenis.start();
    ScrollTrigger.refresh();
  }, null, 0);
  
  if(document.querySelector('[data-transition-animation="fade-before"]')) {
    tl.fromTo('[data-transition-animation="fade-before"]', {
      y: "3em",
      opacity: 0,
    }, {
      y: "0em",
      opacity: 1,
      rotate: 0.001,
      stagger: 0.1,
      duration: 1.5,
      ease: "elastic.out(1,0.8)",
      clearProps: "all"
    }, 0);
  }
  
  if(document.querySelector('[data-transition-animation="words"]')) {
    tl.fromTo($('[data-transition-animation="words"] .single-word-inner'), {
      rotate: 0.001,
      yPercent: 130,
    }, {
      yPercent: 0,
      scale: 1,
      rotate: 0.001,
      stagger: 0.1,
      duration: 1.5  ,
      ease: "elastic.out(1,0.8)",
      clearProps: "all"
    }, 0.1);
  }

  if(document.querySelector('[data-transition-animation="fade-after"]')) {
    tl.fromTo('[data-transition-animation="fade-after"]', {
       y: "3em",
       opacity: 0,
    }, {
       y: "0em",
       opacity: 1,
       rotate: 0.001,
       stagger: 0.1,
       duration: 1.5,
       ease: "elastic.out(1,0.8)",
       clearProps: "all"
    }, "< 0.3");
  }
  
  if(document.querySelector('[data-transition-animation="bounce-before"]')) {
    tl.fromTo('[data-transition-animation="bounce-before"]', {
       scale: 0,
    }, {
       scale: 1,
       rotate: 0.001,
       stagger: 0.1,
       duration: 1.5,
       ease: "elastic.out(1,0.8)",
       clearProps: "all"
    }, "0");
  }
  
  if(document.querySelector('.y25q1-header__col-cards')) {
    
    tl.set('.y25q1-header__col-cards', {
      pointerEvents: "none"
    }, "0");
    
    tl.fromTo('.y25q1-header__col-cards', {
       clipPath: "inset(50% 50% 50% 50% round 1em)",
    }, {
       clipPath: "inset(0% 0% 0% 0% round 1em)",
       duration: 1.5,
       ease: "Expo.easeOut",
       stagger: 0.1,
       clearProps: "all"
    }, "0");
    
  }
  



}

function initPageTransitions() {

  // # Common: leave (Before Offset)
  async function commonLeaveBeforeOffset(data) {
    pageTransitionIn(data.current);
    initBasicFunctions();
    $('[data-navigation-status]').attr('data-navigation-status', 'not-active');
  }

  // # Common: leave (After Offset)
  async function commonLeaveAfterOffset(data) {
    lenis.destroy();
    killAllScrollTriggers();
    data.current.container.remove();
    $('[data-navigation-status]').attr('data-navigation-status', 'not-active');
    $('[data-scrolling-direction]').attr('data-scrolling-direction', 'down');
    $('[data-scrolling-started]').attr('data-scrolling-started', 'false');
  }

  // # Common: enter
  async function commonEnter(data) {
    initBarbaNavUpdate(data);
    pageTransitionOut(data.next);
  }

  // # Common: beforeEnter
  async function commonBeforeEnter(data) {
    ScrollTrigger.getAll().forEach(t => t.kill());
    initResetWebflow(data);
    initSmoothScroll(data.next.container);
    initScript();
  }

  // # Common: afterEnter
  async function commonAfterEnter(data) {
    window.scrollTo(0, 0);
    ScrollTrigger.refresh();
  }

  barba.init({
    sync: true,
    debug: false,
    timeout: 7000,
    preventRunning: true,
    prevent: function ({ el }) {
      if (el.hasAttribute("data-barba-prevent")) {
        return true;
      }
    },
    transitions: [{
      name: 'self',
      async leave(data) {
        await commonLeaveBeforeOffset(data);
        await delay(transitionOffset);
        await commonLeaveAfterOffset(data);
      },
      async enter(data) {
        await commonEnter(data);
      },
      async beforeEnter(data) {
        await commonBeforeEnter(data);
      },
      async afterEnter(data) {
        await commonAfterEnter(data);
      }
    }, {
      name: 'default',
      once(data) {
        document.fonts.ready.then(function () {
          initSmoothScroll(data.next.container);
          initScript();
          initLoader();
        });
      },
      async leave(data) {
        await commonLeaveBeforeOffset(data);
        await delay(transitionOffset);
        await commonLeaveAfterOffset(data);
      },
      async enter(data) {
        await commonEnter(data);
      },
      async beforeEnter(data) {
        await commonBeforeEnter(data);
      },
      async afterEnter(data) {
        await commonAfterEnter(data);
      }
    }]
  });

  function initSmoothScroll(container) {
    initLenis();
    ScrollTrigger.refresh();
  }

  // Function to kill all ScrollTrigger data
  function killAllScrollTriggers() {
    if (typeof ScrollTrigger !== 'undefined') {
      ScrollTrigger.killAll(); // Kill all ScrollTrigger instances
    }
  }

  // Reset scroll on page next
  history.scrollRestoration = "manual";
}

function initLenis() {

  // Lenis: https://github.com/studio-freight/lenis
  lenis = new Lenis({
    // duration: 1,
    lerp: 0.165,
    wheelMultiplier: 1.25,
  });

  lenis.on('scroll', ScrollTrigger.update);

  gsap.ticker.add((time) => {
    lenis.raf(time * 1000);
  });

  gsap.ticker.lagSmoothing(0);
}

// Don't touch
function delay(n) {
  n = n || 2000;
  return new Promise((done) => {
    setTimeout(() => {
      done();
    }, n);
  });
}

