  // Close Navigation
  $('[data-navigation-toggle="close"]').click(function () {
    $('[data-navigation-status]').attr('data-navigation-status', 'not-active');
  });

  // Key ESC - Close Navigation
  $(document).keydown(function (e) {
    if (e.keyCode == 27) {
      if ($('[data-navigation-status]').attr('data-navigation-status') == 'active') {
        $('[data-navigation-status]').attr('data-navigation-status', 'not-active');
      }
    }
  });
  
  // Toggle Card
  $("[data-toggle-cards-init]").each(function(index){
    var $toggle = $(this),
        $cards  = $toggle.find('[data-toggle-cards-controls] [data-card-id]');
    $toggle.data('transitioning', false);
    
    // Helper: Check if element is at least partially in the viewport.
    function isScrolledIntoView($elem) {
      var elemTop = $elem.offset().top,
          elemBottom = elemTop + $elem.outerHeight(),
          viewportTop = $(window).scrollTop(),
          viewportBottom = viewportTop + $(window).height();
      return elemBottom > viewportTop && elemTop < viewportBottom;
    }
    
    // Start auto loop: switch card every 3000ms if container is in view.
    function startAutoLoop(){
      var autoLoop = setInterval(function(){
        if($toggle.data('transitioning')) return;
        if(!isScrolledIntoView($toggle)) return; // Only proceed if in view.
        
        var currentId    = $toggle.find('[data-card-status="active"]').attr('data-card-id'),
            currentIndex = $cards.index($cards.filter('[data-card-id="'+ currentId +'"]')),
            nextIndex    = (currentIndex + 1) % $cards.length;
        $cards.eq(nextIndex).trigger('click', [true]);
      }, 3000);
      $toggle.data('autoLoop', autoLoop);
    }
    
    // Use a unique namespace for each container's scroll event.
    var scrollNS = 'scroll.autoLoop' + index;
    
    // If container is in view on load, start auto loop; else wait for scroll.
    if(isScrolledIntoView($toggle)){
      startAutoLoop();
    } else {
      $(window).on(scrollNS, function(){
         if(isScrolledIntoView($toggle)){
             startAutoLoop();
             $(window).off(scrollNS);
         }
      });
    }
    
    // Click handler for toggling cards.
    $cards.click(function(e, autoTriggered){
      if(!autoTriggered) clearInterval($toggle.data('autoLoop'));
      if($toggle.data('transitioning')) return;
      
      var cardID = $(this).attr('data-card-id');
      if($(this).attr('data-card-status') === 'not-active'){
        $toggle.data('transitioning', true);
        $toggle.find('[data-card-status="active"]').attr('data-card-status','transitioning')
          .siblings().attr('data-card-status','not-active');
        $toggle.find('[data-card-id="'+ cardID +'"]').attr('data-card-status','active');
        setTimeout(function(){
          $toggle.find('[data-card-id="'+ cardID +'"]').siblings().attr('data-card-status','not-active');
          $toggle.data('transitioning', false);
        }, 1000);
      }
    });
    
    // Find the element with the highest innerHeight from its [data-calc-height-target] child.
    var highest = 0, $highest;
    $toggle.find('[data-calc-height]').each(function(){
      var h = $(this).find('[data-calc-height-target]').innerHeight();
      if(h > highest){ highest = h; $highest = $(this); }
    });
    $toggle.find('[data-calc-height]').removeClass('is--relative');
    $highest && $highest.addClass('is--relative');
  });
  
  
  // Dynamic update current year
  const currentYear = new Date().getFullYear();
  const currentYearElements = document.querySelectorAll('[data-current-year]');
  currentYearElements.forEach(currentYearElement => {
    currentYearElement.textContent = currentYear;
  });
  
  
  $('[data-accordion-css-init]').each(function() {
    var accordion = $(this);
    var accordionCloseSiblings = accordion.attr('data-accordion-close-siblings') === 'true';

    accordion.on('click', '[data-accordion-toggle]', function() {
      var singleAccordion = $(this).closest('[data-accordion-status]');

      if (singleAccordion.attr('data-accordion-status') === 'active') {
        singleAccordion.attr('data-accordion-status', 'not-active');
      } else {
        // Close siblings if specified
        if (accordionCloseSiblings) {
          singleAccordion.siblings('[data-accordion-status="active"]').attr('data-accordion-status', 'not-active');
        }
        singleAccordion.attr('data-accordion-status', 'active');
        setTimeout(function(){
          lenis.destroy();
          setTimeout(function(){
            initLenis();
            ScrollTrigger.refresh();
          }, 10);
        }, 600);
      }
      
    });
  });
  
  // $("[data-toggle-tabs-init]").each(function () {
