  //   // Initialize a flag to prevent multiple rapid transitions
  //   toggleCards.data('transitioning', false);
    
  //   toggleCards.find('[data-toggle-cards-controls] [data-card-id]').click(function(){
  //     // Ignore click if a transition is already in progress
  //     if (toggleCards.data('transitioning')) return;
      
