/**
 * Check Theme of Sections
 */
function initCheckTheme() {

  function checkThemeSection() {
    var themeSections = document.querySelectorAll("[data-theme-section]");
    var themeObserverOffset = $(".nav-bar").innerHeight();

    themeSections.forEach(function (themeSection) {
      var themeSectionTop = themeSection.getBoundingClientRect().top;
      var themeSectionBottom = themeSection.getBoundingClientRect().bottom;

      if (themeSectionTop <= themeObserverOffset && themeSectionBottom >= themeObserverOffset) {

        // Check [data-theme-section]
        var themeSectionActive = $(themeSection).attr('data-theme-section');
        if ($('[data-theme-nav]').attr('data-theme-nav') !== themeSectionActive) {
          $('[data-theme-nav]').attr('data-theme-nav', themeSectionActive);
        }

        // Check [data-bg-section]
        var bgSectionActive = $(themeSection).attr('data-bg-section');
        if ($('[data-bg-nav]').attr('data-bg-nav') !== bgSectionActive) {
          $('[data-bg-nav]').attr('data-bg-nav', bgSectionActive);
        }
      }
    });
  }

  // Reference to the scroll event handler
  function startThemeCheck() {
    document.addEventListener("scroll", checkThemeSection);
  }

  function stopThemeCheck() {
    document.removeEventListener("scroll", checkThemeSection);
  }

  // Initial check and start listening for scroll events
  checkThemeSection();
  startThemeCheck();

  // Clean up and reset on page transition
  barba.hooks.beforeLeave(() => {
    stopThemeCheck(); // Remove the scroll event listener
  });

  barba.hooks.after(() => {
    checkThemeSection(); // Re-check the theme immediately after the transition
    startThemeCheck(); // Reattach the scroll event listener
  });
}

/**
 * Progress Navigation with Indicator
 */
function initProgressNavigation() {
  // Cache the parent container
  let $navProgress = $('.nav-progress');

  // Create or select the moving indicator
  let $indicator = $navProgress.find('.nav-progress__indicator');
  if (!$indicator.length) {
    $indicator = $('<div class="nav-progress__indicator"></div>').appendTo($navProgress);
  }
  
  // Function to update the indicator based on the active nav link
  function updateIndicator($activeLink) {
    let parentWidth = $navProgress.width();
    let linkPos = $activeLink.position(); // relative to .nav-progress
    let linkWidth = $activeLink.outerWidth();
    let linkHeight = $activeLink.outerHeight();
    
    // Calculate percentage values relative to parent width
    let leftPercent = (linkPos.left / parentWidth) * 100;
    let widthPercent = (linkWidth / parentWidth) * 100;
    
    // Update the indicator with a smooth CSS transition (set in your CSS)
    $indicator.css({
      left: leftPercent + '%',
      width: widthPercent + '%'
    });
  }
  
  // Get all anchor sections
  let progressAnchors = gsap.utils.toArray('.anchor-group');

  progressAnchors.forEach((progressAnchor) => {
    let anchorID = $(progressAnchor).attr('id');
    
    ScrollTrigger.create({
      trigger: progressAnchor,
      start: '0% 50%',
      end: '100% 50%',
      onEnter: () => {
        let $activeLink = $navProgress.find('[data-anchor-target="#' + anchorID + '"]');
        $activeLink.addClass('is--active').siblings().removeClass('is--active');
        updateIndicator($activeLink);
      },
      onEnterBack: () => {
        let $activeLink = $navProgress.find('[data-anchor-target="#' + anchorID + '"]');
        $activeLink.addClass('is--active').siblings().removeClass('is--active');
        updateIndicator($activeLink);
      }
    });
  });
}

/**
 * Osmo Modal Basic
 */
function initModalBasic() {

  const modalGroup = document.querySelector('[data-modal-group-status]');
  const modals = document.querySelectorAll('[data-modal-name]');
  const modalTargets = document.querySelectorAll('[data-modal-target]');

  // Open modal
  modalTargets.forEach((modalTarget) => {
    modalTarget.addEventListener('click', function () {
      const modalTargetName = this.getAttribute('data-modal-target');

      // Close all modals and pause all videos first
      modalTargets.forEach((target) => target.setAttribute('data-modal-status', 'not-active'));
      modals.forEach((modal) => modal.setAttribute('data-modal-status', 'not-active'));
      document.querySelectorAll('.modal__card video').forEach(function(video) {
        video.pause();
        video.currentTime = 0;
      });

      // Activate clicked modal
      document.querySelector(`[data-modal-target="${modalTargetName}"]`).setAttribute('data-modal-status', 'active');
      document.querySelector(`[data-modal-name="${modalTargetName}"]`).setAttribute('data-modal-status', 'active');

      // Play video in the opened modal
      const openedModal = document.querySelector(`[data-modal-name="${modalTargetName}"]`);
      if (openedModal) {
        const video = openedModal.querySelector('video');
        if (video) {
          video.currentTime = 0;
          video.play();
        }
      }

      // Set group to active
      if (modalGroup) {
        modalGroup.setAttribute('data-modal-group-status', 'active');
      }
    });
  });

  // Close modal
  document.querySelectorAll('[data-modal-close]').forEach((closeBtn) => {
    closeBtn.addEventListener('click', closeAllModals);
  });

  // Close modal on `Escape` key
  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape') {
      closeAllModals();
    }
  });

  // Function to close all modals
  function closeAllModals() {
    modalTargets.forEach((target) => target.setAttribute('data-modal-status', 'not-active'));
    modals.forEach((modal) => modal.setAttribute('data-modal-status', 'not-active'));
    
    document.querySelectorAll('.modal__card video').forEach(function(video) {
      video.pause();
      video.currentTime = 0;
    });
    
    if (modalGroup) {
      modalGroup.setAttribute('data-modal-group-status', 'not-active');
    }
  }
}

/**
 * Flickity Osmo
 */
function initFlickitySlider() {
  // Select all slider groups with the specified data attribute
  const sliderCards = document.querySelectorAll('[data-flickity-type="cards"]');
  
  sliderCards.forEach((slider, index) => {
    // Give each slider a unique ID
    const sliderIndexID = 'flickity-type-cards-id-' + index;
    slider.id = sliderIndexID; 
    
    // Count slides
    let slidesCount = slider.querySelectorAll('[data-flickity-item]').length;
    slider.setAttribute('data-flickity-count', slidesCount);
    
    // Set Active status
    slider.setAttribute('data-flickity-status', 'active');
    
    // Select the element containing the slide list
    const sliderEl = document.querySelector('#' + sliderIndexID + ' [data-flickity-list]');
    if (!sliderEl) return;
    
    // Initialize Flickity on the slider element
    const flickitySlider = new Flickity(sliderEl, {
      watchCSS: true,
      contain: true,
      wrapAround: false,
      dragThreshold: 10,
      prevNextButtons: false,
      pageDots: false,
      cellAlign: 'left',
      selectedAttraction: 0.015,
      friction: 0.25,
      percentPosition: true,
      freeScroll: false,
      on: {
        dragStart: () => {
          // Disable pointer events during drag
          sliderEl.style.pointerEvents = "none";
        },
        dragEnd: () => {
          // Re-enable pointer events after drag
          sliderEl.style.pointerEvents = "auto";
        },
        change: function () {
          updateArrows();
          updateDots();
        }
      }
    });
    
    // Get Flickity instance data
    const flickity = Flickity.data(sliderEl);
    
    // Set up previous click functionality
    const prevButton = slider.querySelector('[data-flickity-control="prev"]');
    if (prevButton) {
      prevButton.setAttribute('disabled', '');
      prevButton.addEventListener('click', function () {
        flickity.previous();
      });
    }
    
    // Set up next click functionality
    const nextButton = slider.querySelector('[data-flickity-control="next"]');
    if (nextButton) {
      nextButton.addEventListener('click', function () {
        flickity.next();
      });
    }
    
    // Update arrows using CSS var(--flick-col) count
    function updateArrows() {
      const inviewColumns = parseInt(window.getComputedStyle(sliderEl).getPropertyValue('--flick-col'), 10);
      if (!flickity.cells[flickity.selectedIndex - 1]) {
        if (prevButton) prevButton.setAttribute('disabled', 'disabled');
        if (nextButton) nextButton.removeAttribute('disabled');
      } else if (!flickity.cells[flickity.selectedIndex + inviewColumns]) {
        if (nextButton) nextButton.setAttribute('disabled', 'disabled');
        if (prevButton) prevButton.removeAttribute('disabled');
      } else {
        if (prevButton) prevButton.removeAttribute('disabled');
        if (nextButton) nextButton.removeAttribute('disabled');
      }
    }
    
    // Set up dots click functionality
    const dots = slider.querySelectorAll('[data-flickity-dot]');
    if (dots.length) {
      dots.forEach((dot, index) => {
        dot.addEventListener('click', function () {
          const inviewColumns = parseInt(window.getComputedStyle(sliderEl).getPropertyValue('--flick-col'), 10);
          const maxIndex = flickity.cells.length - inviewColumns;
          let targetIndex = index;
          if (targetIndex > maxIndex) {
            targetIndex = maxIndex;
          }
          flickity.select(targetIndex);
        });
      });
    }
    
    // Update dots using CSS var(--flick-col) count
    function updateDots() {
      const inviewColumns = parseInt(window.getComputedStyle(sliderEl).getPropertyValue('--flick-col'), 10);
      const maxIndex = flickity.cells.length - inviewColumns;
      const activeIndex = flickity.selectedIndex < maxIndex ? flickity.selectedIndex : maxIndex;
      const dots = slider.querySelectorAll('[data-flickity-dot]');
      dots.forEach((dot, index) => {
        dot.setAttribute('data-flickity-dot', index === activeIndex ? 'active' : '');
      });
    }
    
  });
}

/**
 * Scrolltrigger Animations Desktop + Mobile
 */
function initScrolltriggerAnimations() {

  $('[data-scroll-animation="words"]').each(function () {
    let triggerElement = $(this);
    let targetElement = $(this).find('.single-word-inner');

    let tl = gsap.timeline({
      scrollTrigger: {
        trigger: triggerElement,
        start: "0% 80%",
        end: "100% 0%",
        toggleActions: "play none none none",
      }
    });

    gsap.set(targetElement, {
      yPercent: 110,
      rotate: 0.001,
    });

    tl.to(targetElement, {
      yPercent: 0,
      rotate: 0.001,
      ease: "Expo.easeOut",
      duration: 1.5,
      stagger: 0.05,
      clearProps: "all"
    });

  });

  $('[data-scroll-animation="fade-before"]').each(function () {
    let triggerElement = $(this);
    let targetElement = $(this);

    let tl = gsap.timeline({
      scrollTrigger: {
        trigger: triggerElement,
        start: "0% 80%",
        end: "100% 0%",
        toggleActions: "play none none none",
      }
    });

    gsap.set(targetElement, {
      y: "2em",
      rotate: 0.001,
      opacity: 0,
    });

    tl.to(targetElement, {
      y: "0em",
      rotate: 0.001,
      opacity: 1,
      ease: "Expo.easeOut",
      duration: 2,
      clearProps: "all"
    });

  });

  $('[data-scroll-animation="group-fade-in"]').each(function () {
    let triggerElement = $(this);
    let targetElement = $(this).find('[data-scroll-animation-target]');

    let tl = gsap.timeline({
      scrollTrigger: {
        trigger: triggerElement,
        start: "0% 80%",
        end: "100% 0%",
        toggleActions: "play none none none",
      }
    });

    gsap.set(targetElement, {
      y: "2em",
      rotate: 0.001,
      opacity: 0,
    });

    tl.to(targetElement, {
      y: "0em",
      rotate: 0.001,
      opacity: 1,
      ease: "Expo.easeOut",
      duration: 2,
      stagger: 0.2,
      clearProps: "all"
    });

  });
  
  $('[data-scroll-animation="bounce-children"]').each(function () {
    let triggerElement = $(this);
    let targetElement = $(this).find("> *");
    if(triggerElement.is('[data-split-words-nomask]') ) {
      targetElement = triggerElement.find('.h2-icon, .single-word');
    }

    let tl = gsap.timeline({
      scrollTrigger: {
        trigger: triggerElement,
        start: "0% 80%",
        end: "100% 0%",
        toggleActions: "play none none none",
      }
    });

    gsap.set(targetElement, {
      y: "1em",
      rotate: 0.001,
      opacity: 0,
    });

    tl.to(targetElement, {
       y: "0em",
      rotate: 0.001,
      opacity: 1,
      ease: "elastic.out(1,0.8)",
      duration: 1.25,
      stagger: 0.075,
      clearProps: "all"
    });

  });
  
  $('.y25q1-prefooter').each(function () {
    let triggerElement = $(this);
    let targetElement = $(this).find('.cover-image');
    
    ScrollTrigger.matchMedia({
      "(min-width: 992px)": function () {

        gsap.from(targetElement, {
          yPercent: -10,
          ease: 'linear',
          scrollTrigger: {
            invalidateOnRefresh: true,
            trigger: triggerElement,
            start: () => "clamp(top bottom)",
            end: () => "clamp(top top)",
            scrub: true
          }
        });
      }
    });
  });

}


